/*
 * Shared keyframes. Components pick them with `animation-name` and set
 * duration and easing from the motion tokens. Plain CSS, so the Vue version
 * can reuse this file unchanged.
 */
@keyframes distill-fade-in {
	from {
		opacity: 0;
	}
}

@keyframes distill-fade-out {
	to {
		opacity: 0;
	}
}

/* Fade + scale from 95%, the standard dialog / popover entrance. */
@keyframes distill-zoom-in {
	from {
		opacity: 0;
		scale: 0.95;
	}
}

@keyframes distill-zoom-out {
	to {
		opacity: 0;
		scale: 0.95;
	}
}

/* Slide in a short distance from a side. Uses `translate` so it composes with transforms. */
@keyframes distill-slide-in-from-top {
	from {
		translate: 0 calc(var(--dui-space-2) * -1);
	}
}

@keyframes distill-slide-in-from-bottom {
	from {
		translate: 0 var(--dui-space-2);
	}
}

@keyframes distill-slide-in-from-left {
	from {
		translate: calc(var(--dui-space-2) * -1) 0;
	}
}

@keyframes distill-slide-in-from-right {
	from {
		translate: var(--dui-space-2) 0;
	}
}

/* Loading placeholders (Skeleton). */
@keyframes distill-pulse {
	50% {
		opacity: 0.5;
	}
}

:root {
	/* Motion */
	--dui-duration-fast: 100ms;
	--dui-duration-normal: 150ms;
	--dui-duration-slow: 200ms;
	--dui-duration-pulse: 2s;
	--dui-ease-out: cubic-bezier(0, 0, 0.2, 1);
	--dui-ease-in: cubic-bezier(0.4, 0, 1, 1);
	--dui-ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
}

/* Defined in this file, after the durations above, so it wins the cascade. */
@media (prefers-reduced-motion: reduce) {
	:root {
		--dui-duration-fast: 0ms;
		--dui-duration-normal: 0ms;
		--dui-duration-slow: 0ms;
		--dui-duration-pulse: 0ms;
	}
}

/*
 * Dark theme. Applies when:
 *   - <html> has class="dark" or data-theme="dark", or
 *   - the OS prefers dark and the page hasn't opted into light
 *     (class="light" or data-theme="light").
 * The values are listed twice because a media query can't share a rule
 * with a plain selector. Keep both blocks identical.
 */
.dark,
[data-theme='dark'] {
	color-scheme: dark;

	--dui-color-background: oklch(0.145 0 0);
	--dui-color-foreground: oklch(0.985 0 0);
	--dui-color-card: oklch(0.205 0 0);
	--dui-color-card-foreground: oklch(0.985 0 0);
	--dui-color-popover: oklch(0.205 0 0);
	--dui-color-popover-foreground: oklch(0.985 0 0);
	--dui-color-primary: oklch(0.922 0 0);
	--dui-color-primary-foreground: oklch(0.205 0 0);
	--dui-color-secondary: oklch(0.269 0 0);
	--dui-color-secondary-foreground: oklch(0.985 0 0);
	--dui-color-muted: oklch(0.269 0 0);
	--dui-color-muted-foreground: oklch(0.708 0 0);
	--dui-color-accent: oklch(0.371 0 0);
	--dui-color-accent-foreground: oklch(0.985 0 0);
	--dui-color-destructive: oklch(0.704 0.191 22.216);
	--dui-color-destructive-foreground: oklch(0.985 0 0);
	--dui-color-success: oklch(0.7 0.17 150);
	--dui-color-border: oklch(1 0 0 / 10%);
	--dui-color-input: oklch(1 0 0 / 15%);
	--dui-color-ring: oklch(0.556 0 0);
	--dui-color-overlay: oklch(0 0 0 / 50%);

	--dui-color-control: color-mix(in oklch, var(--dui-color-input) 30%, transparent);
	--dui-color-control-hover: color-mix(in oklch, var(--dui-color-input) 50%, transparent);
	--dui-color-tab-active: var(--dui-color-control);
	--dui-color-tab-active-border: var(--dui-color-input);
	--dui-color-switch-track: color-mix(in oklch, var(--dui-color-input) 80%, transparent);
	--dui-color-switch-thumb: var(--dui-color-foreground);
	--dui-color-switch-thumb-checked: var(--dui-color-primary-foreground);
}

@media (prefers-color-scheme: dark) {
	:root:not(.light):not([data-theme='light']) {
		color-scheme: dark;

		--dui-color-background: oklch(0.145 0 0);
		--dui-color-foreground: oklch(0.985 0 0);
		--dui-color-card: oklch(0.205 0 0);
		--dui-color-card-foreground: oklch(0.985 0 0);
		--dui-color-popover: oklch(0.205 0 0);
		--dui-color-popover-foreground: oklch(0.985 0 0);
		--dui-color-primary: oklch(0.922 0 0);
		--dui-color-primary-foreground: oklch(0.205 0 0);
		--dui-color-secondary: oklch(0.269 0 0);
		--dui-color-secondary-foreground: oklch(0.985 0 0);
		--dui-color-muted: oklch(0.269 0 0);
		--dui-color-muted-foreground: oklch(0.708 0 0);
		--dui-color-accent: oklch(0.371 0 0);
		--dui-color-accent-foreground: oklch(0.985 0 0);
		--dui-color-destructive: oklch(0.704 0.191 22.216);
		--dui-color-destructive-foreground: oklch(0.985 0 0);
		--dui-color-success: oklch(0.7 0.17 150);
		--dui-color-border: oklch(1 0 0 / 10%);
		--dui-color-input: oklch(1 0 0 / 15%);
		--dui-color-ring: oklch(0.556 0 0);
		--dui-color-overlay: oklch(0 0 0 / 50%);

		--dui-color-control: color-mix(in oklch, var(--dui-color-input) 30%, transparent);
		--dui-color-control-hover: color-mix(in oklch, var(--dui-color-input) 50%, transparent);
		--dui-color-tab-active: var(--dui-color-control);
		--dui-color-tab-active-border: var(--dui-color-input);
		--dui-color-switch-track: color-mix(in oklch, var(--dui-color-input) 80%, transparent);
		--dui-color-switch-thumb: var(--dui-color-foreground);
		--dui-color-switch-thumb-checked: var(--dui-color-primary-foreground);
		--dui-color-switch-track: color-mix(in oklch, var(--dui-color-input) 80%, transparent);
		--dui-color-switch-thumb: var(--dui-color-foreground);
		--dui-color-switch-thumb-checked: var(--dui-color-primary-foreground);
	}
}

/*
 * Light theme. Semantic names mirror shadcn/ui so they feel familiar.
 * Used by default, and when <html> has data-theme="light".
 */
:root,
[data-theme='light'] {
	color-scheme: light;

	--dui-color-background: oklch(1 0 0);
	--dui-color-foreground: oklch(0.145 0 0);
	--dui-color-card: oklch(1 0 0);
	--dui-color-card-foreground: oklch(0.145 0 0);
	--dui-color-popover: oklch(1 0 0);
	--dui-color-popover-foreground: oklch(0.145 0 0);
	--dui-color-primary: oklch(0.205 0 0);
	--dui-color-primary-foreground: oklch(0.985 0 0);
	--dui-color-secondary: oklch(0.97 0 0);
	--dui-color-secondary-foreground: oklch(0.205 0 0);
	--dui-color-muted: oklch(0.97 0 0);
	--dui-color-muted-foreground: oklch(0.556 0 0);
	--dui-color-accent: oklch(0.97 0 0);
	--dui-color-accent-foreground: oklch(0.205 0 0);
	--dui-color-destructive: oklch(0.577 0.245 27.325);
	--dui-color-destructive-foreground: oklch(0.985 0 0);
	--dui-color-success: oklch(0.6 0.17 150);
	--dui-color-border: oklch(0.922 0 0);
	--dui-color-input: oklch(0.922 0 0);
	--dui-color-ring: oklch(0.708 0 0);
	--dui-color-overlay: oklch(0 0 0 / 10%);

	/* Surfaces that differ by theme in more than color: outline controls, active tabs and switches. */
	--dui-color-control: transparent;
	--dui-color-control-hover: var(--dui-color-muted);
	--dui-color-tab-active: var(--dui-color-background);
	--dui-color-tab-active-border: transparent;
	--dui-color-switch-track: var(--dui-color-input);
	--dui-color-switch-thumb: var(--dui-color-background);
	--dui-color-switch-thumb-checked: var(--dui-color-background);
}

/*
 * distill-ui design tokens.
 *
 * Every color, spacing, radius, shadow, font, motion and z-index value used by
 * the components comes from a custom property defined here or in a theme file.
 * Importing this file brings in the light and dark themes and the shared
 * keyframes too.
 */
@import './themes/light.css';
@import './themes/dark.css';
@import './motion.css';

:root {
	/* Spacing: 1 step = 0.25rem (4px at the default font size). */
	--dui-space-0-5: 0.125rem;
	--dui-space-1: 0.25rem;
	--dui-space-1-5: 0.375rem;
	--dui-space-2: 0.5rem;
	--dui-space-2-5: 0.625rem;
	--dui-space-3: 0.75rem;
	--dui-space-4: 1rem;
	--dui-space-5: 1.25rem;
	--dui-space-6: 1.5rem;
	--dui-space-8: 2rem;
	--dui-space-10: 2.5rem;
	--dui-space-12: 3rem;

	/* Radius: one knob (--dui-radius) scales the whole set. */
	--dui-radius: 0.625rem;
	--dui-radius-sm: calc(var(--dui-radius) * 0.6);
	--dui-radius-md: calc(var(--dui-radius) * 0.8);
	--dui-radius-lg: var(--dui-radius);
	--dui-radius-xl: calc(var(--dui-radius) * 1.4);
	--dui-radius-full: 9999px;

	/* Shadows */
	--dui-shadow-xs: 0 1px 2px 0 oklch(0 0 0 / 5%);
	--dui-shadow-sm: 0 1px 3px 0 oklch(0 0 0 / 10%), 0 1px 2px -1px oklch(0 0 0 / 10%);
	--dui-shadow-md: 0 4px 6px -1px oklch(0 0 0 / 10%), 0 2px 4px -2px oklch(0 0 0 / 10%);
	--dui-shadow-lg: 0 10px 15px -3px oklch(0 0 0 / 10%), 0 4px 6px -4px oklch(0 0 0 / 10%);

	/* Fonts */
	--dui-font-sans:
		ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
	--dui-font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, 'Liberation Mono', monospace;

	--dui-text-xs: 0.75rem;
	--dui-text-xs-line-height: 1rem;
	--dui-text-sm: 0.875rem;
	--dui-text-sm-line-height: 1.25rem;
	--dui-text-base: 1rem;
	--dui-text-base-line-height: 1.5rem;
	--dui-text-lg: 1.125rem;
	--dui-text-lg-line-height: 1.75rem;

	--dui-font-weight-normal: 400;
	--dui-font-weight-medium: 500;
	--dui-font-weight-semibold: 600;

	/* Focus ring */
	--dui-ring-width: 3px;

	/* Stacking */
	--dui-z-dropdown: 50;
	--dui-z-overlay: 50;
	--dui-z-modal: 50;
	--dui-z-popover: 50;
	--dui-z-toast: 100;
}

/*
 * Colors derived from the theme colors, so components can use one short name for
 * hover states and tints. Listed on every theme selector so they follow the theme
 * wherever it's applied.
 */
:root,
.light,
.dark,
[data-theme] {
	--dui-color-primary-hover: color-mix(in oklch, var(--dui-color-primary) 80%, transparent);
	--dui-color-secondary-hover: color-mix(in oklch, var(--dui-color-secondary) 80%, transparent);

	/* Destructive as a soft tint with readable text, for buttons, badges and alerts. */
	--dui-color-destructive-subtle: color-mix(
		in oklch,
		var(--dui-color-destructive) 10%,
		transparent
	);
	--dui-color-destructive-subtle-hover: color-mix(
		in oklch,
		var(--dui-color-destructive) 20%,
		transparent
	);
	/* Pulled toward the foreground so text passes AA contrast on the tint. */
	--dui-color-destructive-text: color-mix(
		in oklch,
		var(--dui-color-destructive) 80%,
		var(--dui-color-foreground)
	);
}
